    public static <T> Optional<T> reduce(T[] items, int size, BinaryOperator<T> accumulator)
    {
        if (size == 0)
        {
            return Optional.empty();
        }
        T result = items[0];
        for (int i = 1; i < size; i++)
        {
            result = accumulator.apply(result, items[i]);
        }
        return Optional.of(result);
    }

    /**
     * @since 8.0
